"""Binary Tree Zigzag Level Order Traversal — BFS, reversing alternate levels.

Time: O(n)   Space: O(width)
"""
from collections import deque
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def zigzagLevelOrder(self, root) -> List[List[int]]:
        if not root:
            return []
        out, queue, left_to_right = [], deque([root]), True
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.popleft()
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            out.append(level if left_to_right else level[::-1])
            left_to_right = not left_to_right
        return out
